BEGIN; SET LOCAL lock_timeout='5s'; DO $operation$ DECLARE data jsonb := $records${"batch":"en-reading-lists-complete-20261116","descriptions":[{"id":100,"authorId":87,"ol":"OL1846076W","title":"The Giver","text":"Jonas grows up in a community that has removed much of life's uncertainty by assigning people their roles and regulating everyday choices. At twelve, he is selected for an unusual responsibility: receiving memories held by one older man. Those experiences reveal feelings and losses that his neighbours cannot understand. The Giver follows his changing view of a society whose apparent security depends on keeping important parts of human life out of reach.","source":"https://openlibrary.org/works/OL1846076W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":179,"authorId":135,"ol":"OL15719630W","title":"Divergent","text":"At the threshold of adulthood, Beatrice must choose a place within a society divided into factions. Her decision takes her away from her familiar life and into demanding initiation trials. As Tris, she discovers that fitting the categories expected of her is more complicated than it seems. Divergent combines physical challenges and growing relationships with a conflict over identity, belonging and the institutions that demand conformity.","source":"https://openlibrary.org/works/OL15719630W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":197,"authorId":19,"ol":"OL5738148W","title":"The Final Empire","text":"For centuries, an immortal ruler has dominated a world where ash falls from the sky and the skaa live under oppression. Vin, a young thief, becomes involved with a group planning an audacious rebellion. Learning to use powers connected to metals changes both her prospects and her understanding of trust. Mistborn, also published as The Final Empire, opens a trilogy that combines a conspiracy against authority with a carefully explained magical system.","source":"https://openlibrary.org/works/OL5738148W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":1326,"authorId":131,"ol":"OL2577482W","title":"The Last Wish","text":"Geralt of Rivia earns his living dealing with monsters, but the people who hire him can be as difficult to understand as the creatures he encounters. These linked stories introduce the witcher through dangerous commissions, bargains and encounters with magic. Familiar fairy-tale patterns become questions about prejudice and responsibility. The Last Wish offers an entry to Geralt's world through shorter adventures rather than a single continuous novel.","source":"https://openlibrary.org/works/OL2577482W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":1360,"authorId":125,"ol":"OL17352669W","title":"A Court of Thorns and Roses","text":"Feyre hunts to support her family through a harsh winter. Killing a wolf brings consequences she could not have anticipated: she is taken into the realm of the fae, creatures she has learned to fear. At an unfamiliar estate, her assumptions about her captor and his world begin to change. A Court of Thorns and Roses opens a romantic fantasy series in which attraction, old obligations and an approaching threat become entangled.","source":"https://openlibrary.org/works/OL17352669W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":1369,"authorId":152,"ol":"OL29226517W","title":"Fourth Wing","text":"Violet Sorrengail expects a future among books, but her mother orders her to enter the training programme for dragon riders. At Basgiath, both the trials and the other candidates can be lethal. Violet must use judgement and ingenuity to survive while navigating loyalties shaped by her family's reputation. Fourth Wing begins the Empyrean series, combining military training, dragons and an intense romantic relationship with questions about the war beyond the college.","source":"https://openlibrary.org/works/OL29226517W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":1387,"authorId":358,"ol":"OL1914022W","title":"The Pillars of the Earth","text":"In twelfth-century England, the effort to build a cathedral draws together craftsmen, clergy, nobles and families struggling for security. Kingsbridge develops through their ambitions and conflicts while political upheaval threatens the work. The Pillars of the Earth follows construction as a long human undertaking, shaped by skill, faith and the unequal distribution of power. Its broad cast and extended timespan make the changing town central to the story.","source":"https://openlibrary.org/works/OL1914022W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":1422,"authorId":749,"ol":"OL515754W","title":"Flowers for Algernon","text":"Charlie Gordon hopes that an experimental procedure will make learning easier for him. A mouse named Algernon has already undergone the treatment, and Charlie records what happens as his own abilities change. New understanding affects how he sees his colleagues, his past and the researchers studying him. Flowers for Algernon explores intelligence alongside friendship, dignity and the responsibilities people owe to someone whose life they have made an experiment.","source":"https://openlibrary.org/works/OL515754W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":1994,"authorId":104,"ol":"OL52114W","title":"The War of the Worlds","text":"Strange objects arriving in the English countryside become the beginning of a Martian invasion. Human weapons and familiar institutions offer little reassurance against machines whose power seems overwhelming. A narrator tries to survive and find his way through the resulting disorder. The War of the Worlds brings an immense threat down to individual encounters, while questioning the confidence of a society accustomed to seeing itself as powerful and secure.","source":"https://openlibrary.org/works/OL52114W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2146,"authorId":1076,"ol":"OL462007W","title":"Peter Pan","text":"Peter Pan takes Wendy Darling and her brothers away from their ordinary home to Neverland. There they encounter the Lost Boys, fairies and pirates, including Captain Hook. Adventure is inseparable from Peter's refusal to grow up, while Wendy's relationship to home becomes increasingly important. J. M. Barrie's story combines play and danger with a more wistful interest in childhood, memory and the changes that come with leaving it behind.","source":"https://openlibrary.org/works/OL462007W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2195,"authorId":1086,"ol":"OL464512W","title":"Wolf Hall","text":"Thomas Cromwell rises from an unpromising background to become influential at the court of Henry VIII. His practical intelligence and ability to read other people are tested by the king's ambitions and the conflicts surrounding his marriage. Wolf Hall presents Tudor politics through close attention to conversations, loyalties and personal risk. It begins Hilary Mantel's trilogy about Cromwell, using a distinctive intimate perspective rather than a distant account of historical events.","source":"https://openlibrary.org/works/OL464512W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2389,"authorId":961,"ol":"OL3171087W","title":"We Have Always Lived in the Castle","text":"Merricat Blackwood lives with her sister Constance and their uncle in a house separated from an increasingly hostile village. The family's past hangs over daily routines that Merricat tries fiercely to protect. When a cousin arrives, the fragile order of their home begins to change. We Have Always Lived in the Castle is a compact gothic novel in which a distinctive narrator shapes what the reader understands about fear, loyalty and isolation.","source":"https://openlibrary.org/works/OL3171087W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2403,"authorId":1177,"ol":"OL17619932W","title":"The Underground Railroad","text":"Cora escapes from a plantation in Georgia and seeks a route towards freedom. In Colson Whitehead's novel, the Underground Railroad becomes an actual network of trains and tunnels beneath the ground. Each stage of her journey exposes another arrangement of power, danger and apparent refuge. The book uses this imagined railway to connect a personal flight from slavery with a wider examination of the systems that sustain racial violence.","source":"https://openlibrary.org/works/OL17619932W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2406,"authorId":1178,"ol":"OL17795349W","title":"Homegoing","text":"Two half-sisters in eighteenth-century Ghana begin family histories that unfold on opposite sides of the Atlantic. One branch remains in West Africa; the other is carried into slavery in America. Homegoing follows their descendants through linked chapters, changing its central character as generations pass. Yaa Gyasi traces how historical forces enter ordinary lives, while showing both the connections people inherit and the knowledge of family that can be lost.","source":"https://openlibrary.org/works/OL17795349W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2600,"authorId":8,"ol":"OL675722W","title":"Oryx and Crake","text":"A man calling himself Snowman survives among the remnants of a society transformed by catastrophe. His memories return to Jimmy, the person he used to be, and to his relationships with Crake and Oryx. Those recollections gradually illuminate a world shaped by corporations, inequality and genetic engineering. Oryx and Crake begins Margaret Atwood's MaddAddam trilogy, moving between an uncertain present and the choices that helped bring it about.","source":"https://openlibrary.org/works/OL675722W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2675,"authorId":1282,"ol":"OL16086747W","title":"The Night Circus","text":"A mysterious circus appears without advance notice and opens after dark. Its extraordinary attractions are also the setting for a contest between Celia and Marco, two young magicians trained for a purpose they do not fully control. As their lives become connected, the people around the circus are drawn into the consequences. The Night Circus places atmosphere and invention at the centre of a story about love, rivalry and promises made by others.","source":"https://openlibrary.org/works/OL16086747W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2685,"authorId":1287,"ol":"OL20656224W","title":"The house in the Cerulean Sea","text":"Linus Baker works for a department overseeing magical children. An assignment takes him to an island orphanage whose unusual residents are considered potentially dangerous. As he spends time with the children and their guardian, Arthur, his official task becomes harder to separate from his own judgement. The House in the Cerulean Sea combines gentle fantasy and romance with questions about prejudice, belonging and the difference between following rules and caring for people.","source":"https://openlibrary.org/works/OL20656224W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2708,"authorId":142,"ol":"OL20197660W","title":"Ninth House","text":"Alex Stern is offered a place at Yale under unusual circumstances. Her benefactors expect her to monitor the university's secret societies, whose rituals have consequences beyond the privileges of their wealthy members. As she investigates, her own troubled past and particular abilities become important to understanding what she encounters. Ninth House opens a dark contemporary fantasy series in which institutional power, occult activity and personal vulnerability are closely connected.","source":"https://openlibrary.org/works/OL20197660W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2716,"authorId":1306,"ol":"OL17358795W","title":"Dark Matter","text":"Physics lecturer Jason Dessen is abducted and wakes to a life that resembles his own but differs in crucial ways. His family and his achievements are no longer where he expects them to be. Trying to return to the people he loves forces him to question what makes one possible life his own. Blake Crouch's Dark Matter turns a speculative scientific premise into a fast-moving thriller about identity, choice and attachment.","source":"https://openlibrary.org/works/OL17358795W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2717,"authorId":1307,"ol":"OL17876096W","title":"Scythe","text":"Humanity has eliminated many causes of suffering and even overcome natural death. To control the population, scythes are entrusted with the power to end lives. Citra and Rowan are selected as apprentices despite not wanting that responsibility. Their training exposes disagreements over how such authority should be exercised. Scythe begins a young-adult series that combines rivalry and suspense with an ethical problem at the heart of an apparently perfected society.","source":"https://openlibrary.org/works/OL17876096W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2718,"authorId":172,"ol":"OL59038W","title":"Never Let Me Go","text":"Kathy looks back on her childhood at Hailsham and on her relationships with Ruth and Tommy. Lessons, friendships and small misunderstandings acquire new significance as she recalls the expectations placed upon them. Kazuo Ishiguro allows the wider circumstances of their lives to emerge gradually through memory. Never Let Me Go is a restrained, unsettling novel about intimacy, loss and the limited choices available to people who have learned to accept their world.","source":"https://openlibrary.org/works/OL59038W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2722,"authorId":1309,"ol":"OL17417W","title":"Rendezvous with Rama","text":"An enormous cylindrical object enters the solar system, and a human crew is sent to investigate before the opportunity passes. Inside, they encounter an environment whose scale and purpose resist easy explanation. Rendezvous with Rama follows their observations and practical decisions as they explore. Arthur C. Clarke builds suspense from discovery itself, leaving room for uncertainty about an intelligence whose priorities may have little to do with the visitors studying it.","source":"https://openlibrary.org/works/OL17417W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2723,"authorId":1,"ol":"OL17837968W","title":"Artemis","text":"Jazz Bashara makes a precarious living in Artemis, a settlement on the Moon, where legal work and small-scale smuggling do not bring the future she wants. A lucrative opportunity draws her into a much more ambitious crime. Carrying it out requires technical skill, but its consequences extend into the struggle over the city's future. Artemis combines a heist plot with the practical vulnerabilities of a community dependent on engineered systems.","source":"https://www.penguinrandomhouse.com/books/250305/artemis-by-andy-weir/9780553448122/","sourceType":"official_publisher","sourceName":"www.penguinrandomhouse.com"},{"id":2724,"authorId":1307,"ol":"OL1954412W","title":"Unwind","text":"In a future society, a legal compromise permits teenagers to be dismantled for their organs while authorities insist that their lives technically continue. Three young people facing this process seek a way to survive outside the system. Unwind follows their flight through a world that has made exploitation sound reasonable. Neal Shusterman combines an action-driven escape story with disturbing questions about bodily autonomy, responsibility and the language used to justify violence.","source":"https://openlibrary.org/works/OL1954412W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2732,"authorId":1306,"ol":"OL20073906W","title":"Recursion","text":"Detective Barry Sutton investigates people troubled by detailed memories of lives they apparently never lived. Elsewhere, neuroscientist Helena Smith is trying to preserve memories through new technology. Their stories converge as the implications become harder to contain. Recursion uses an expanding speculative mystery to explore how memory shapes identity and relationships. Its increasingly urgent decisions make scientific ambition inseparable from grief and the desire to undo the past.","source":"https://openlibrary.org/works/OL20073906W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2768,"authorId":1331,"ol":"OL19736215W","title":"Then She Was Gone","text":"Years after her daughter Ellie's disappearance, Laurel Mack is trying to rebuild her life. Meeting a new man seems to offer a way forward, until an unsettling resemblance raises questions she cannot put aside. Then She Was Gone moves between the aftermath of loss and the circumstances around the missing girl. Lisa Jewell builds a domestic mystery in which ordinary encounters become difficult to separate from the unresolved past.","source":"https://openlibrary.org/works/OL19736215W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2776,"authorId":1336,"ol":"OL19353453W","title":"The Couple Next Door","text":"Anne and Marco attend a dinner party next door while their baby remains at home. When the child disappears, their decisions attract intense scrutiny and the investigation begins to expose secrets within the family. The Couple Next Door keeps its focus on a small circle of people whose accounts cannot simply be accepted. Shari Lapena uses a familiar domestic setting to explore suspicion, vulnerability and the distance between appearances and private behaviour.","source":"https://openlibrary.org/works/OL19353453W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2779,"authorId":1338,"ol":"OL24161797W","title":"The Last Thing He Told Me","text":"Before disappearing, Owen leaves his wife Hannah a brief instruction to protect his teenage daughter Bailey. Hannah and Bailey have not formed an easy relationship, but finding out what happened requires them to work together. Their search unsettles what both thought they knew about Owen. The Last Thing He Told Me combines a family mystery with the developing bond between a stepmother and a girl whose trust she must earn.","source":"https://openlibrary.org/works/OL24161797W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2795,"authorId":1331,"ol":"OL20822606W","title":"Watching you","text":"After returning to Bristol, Joey becomes fascinated by a respected head teacher living nearby. Around them, other neighbours and family members are also watching, making assumptions and keeping information to themselves. A murder brings those intersecting lives under a different kind of scrutiny. Watching You builds suspense from partial perspectives, showing how a seemingly familiar neighbourhood can conceal motives that are difficult to recognise from the outside.","source":"https://openlibrary.org/works/OL20822606W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2810,"authorId":1352,"ol":"OL19729767W","title":"In a Dark, Dark Wood","text":"Crime writer Nora receives an unexpected invitation to a hen weekend for a friend she has not seen in years. The gathering takes place in an isolated glass house in the woods, where old tensions are difficult to avoid. When events turn violent, her memories become crucial to understanding what happened. In a Dark, Dark Wood uses a reunion and its uneasy social expectations as the setting for a psychological mystery.","source":"https://openlibrary.org/works/OL19729767W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2846,"authorId":8,"ol":"OL675774W","title":"The Year of the Flood","text":"Toby and Ren survive a catastrophe that has devastated the society around them. Their memories lead back to God's Gardeners, a community combining ecological beliefs with preparation for disaster. Through their different experiences, The Year of the Flood revisits the world of Oryx and Crake from other social positions. Margaret Atwood connects survival with questions about exploitation, faith and the value assigned to human and non-human life.","source":"https://openlibrary.org/works/OL675774W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2864,"authorId":1382,"ol":"OL19721856W","title":"The road to winter","text":"After an epidemic and the violence that followed, Finn survives on a rugged Australian coast with his dog. Hunting, fishing and avoiding a dangerous gang have become the pattern of his life. The arrival of Rose, a girl escaping captivity, makes remaining isolated a much harder choice. The Road to Winter begins a young-adult survival series in which practical resourcefulness is tested by responsibility towards other people.","source":"https://openlibrary.org/works/OL19721856W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":2971,"authorId":1467,"ol":"OL2827199W","title":"Life of Pi","text":"Pi's family journey across the ocean ends in a shipwreck. On the Pacific, he must find ways to stay alive in a lifeboat where a Bengal tiger presents an extraordinary additional danger. Food, water and shelter become urgent concerns, but the telling of his experience also matters. Life of Pi brings a physical survival story together with questions about faith, interpretation and the ways people make meaning from events.","source":"https://openlibrary.org/works/OL2827199W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":3129,"authorId":1529,"ol":"OL16700025W","title":"Flight behavior","text":"Dellarobia Turnbow discovers an extraordinary gathering of butterflies in the mountains near her Appalachian home. The phenomenon draws scientific attention and disrupts the expectations of her family and community. Flight Behaviour connects an environmental mystery to the pressures of poverty, marriage and differing beliefs. Barbara Kingsolver follows how a large ecological question becomes personal when it appears in a place whose residents cannot easily separate their livelihood from the land.","source":"https://openlibrary.org/works/OL16700025W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":3145,"authorId":1533,"ol":"OL20027050W","title":"I let you go","text":"After a fatal hit-and-run, Jenna leaves her familiar life for the Welsh coast. She hopes distance and a new routine will help her move forward, while a police investigation continues to pursue what happened. I Let You Go draws these strands together through withheld information and changing interpretations. Clare Mackintosh places grief, fear and the possibility of escape at the centre of a psychological thriller about a past that remains unresolved.","source":"https://openlibrary.org/works/OL20027050W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":4192,"authorId":398,"ol":"OL26770888W","title":"The American Roommate Experiment","text":"Rosie has left her job to concentrate on writing romance, only to encounter writer's block and an apartment that becomes uninhabitable. Staying at a friend's home brings her into unexpected proximity with Lucas, who is already using the same space. His offer of practice dates to inspire her work complicates their temporary arrangement. The American Roommate Experiment follows the distance between imagined romantic situations and feelings that become harder to treat as research.","source":"https://openlibrary.org/works/OL26770888W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":4193,"authorId":2193,"ol":"OL1858668W","title":"Wide Sargasso Sea","text":"Antoinette grows up in the Caribbean in a society marked by the aftermath of slavery and by sharp divisions of race and wealth. Her marriage brings another set of expectations and misunderstandings into her life. Wide Sargasso Sea gives a history and perspective to the woman confined in the attic in Jane Eyre. Jean Rhys uses shifting voices to examine belonging, possession and the power to determine someone else's story.","source":"https://openlibrary.org/works/OL1858668W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":4218,"authorId":2202,"ol":"OL17762217W","title":"Pachinko","text":"Sunja's choices in early twentieth-century Korea set a family on a course that leads to Japan. Across generations, its members work to build lives amid discrimination and restrictions on belonging. Pachinko follows their businesses, relationships and compromises as historical changes reshape what seems possible. Min Jin Lee combines the breadth of a family saga with attention to the everyday decisions through which people try to protect those who depend on them.","source":"https://openlibrary.org/works/OL17762217W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":4324,"authorId":875,"ol":"OL5730765W","title":"Can You Keep A Secret?","text":"During a frightening flight, Emma tells a stranger the secrets she normally keeps from her colleagues, family and boyfriend. She expects never to see him again, but he reappears in a position that makes those confessions much less private. Can You Keep a Secret? turns workplace embarrassment and romantic uncertainty into comedy. Sophie Kinsella follows a heroine whose carefully managed image becomes increasingly difficult to maintain.","source":"https://openlibrary.org/works/OL5730765W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":4527,"authorId":2325,"ol":"OL19956847W","title":"Foster","text":"A young girl is sent to stay with a couple on a farm in rural Ireland, without a clear understanding of how long she will remain. Their attention and everyday kindness offer experiences different from those she has known at home. In Foster, small observations carry much of the story's emotional weight. Claire Keegan explores care, silence and a child's growing awareness of the adults whose decisions shape her life.","source":"https://openlibrary.org/works/OL19956847W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":4751,"authorId":2460,"ol":"OL876504W","title":"Seta","text":"In nineteenth-century France, a silkworm trader travels to Japan to obtain healthy eggs for an industry threatened by disease. There, an encounter becomes the focus of a longing he cannot readily explain or act upon. Silk moves between distant places and the life awaiting him at home. Alessandro Baricco tells the story through short, spare passages that leave much of its emotional meaning in repetition, uncertainty and what remains unsaid.","source":"https://openlibrary.org/works/OL876504W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":4778,"authorId":1352,"ol":"OL18020460W","title":"The Woman In Cabin 10","text":"Travel journalist Lo Blacklock joins a luxury cruise and believes she witnesses a woman being thrown overboard. Yet the passenger records appear to show that nobody is missing. Her attempts to investigate make it difficult to know whom she can trust aboard the ship. The Woman in Cabin 10 combines a confined setting with uncertainty over an observation that other people are unwilling to accept.","source":"https://openlibrary.org/works/OL18020460W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":7677,"authorId":4527,"ol":"OL20055689W","title":"The stranger in the woods","text":"Michael Finkel investigates the life of Christopher Knight, who lived alone for decades in the woods of Maine. Interviews and accounts from the surrounding community reveal how he endured isolation and harsh winters, while depending on supplies stolen from nearby properties. The Stranger in the Woods is non-fiction about solitude, survival and the impact of withdrawal on others. It asks what this unusual life can and cannot tell us about independence.","source":"https://openlibrary.org/works/OL20055689W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8365,"authorId":5071,"ol":"OL20664315W","title":"The Flatshare","text":"Tiffy needs affordable accommodation after a breakup, while Leon works nights and needs extra income. They agree to share a flat and its bed at different times, initially communicating through notes rather than meeting. As their correspondence becomes more personal, their separate difficulties enter the arrangement. The Flatshare combines a playful romantic premise with questions about trust, support and learning to recognise an unhealthy relationship.","source":"https://openlibrary.org/works/OL20664315W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8367,"authorId":5072,"ol":"OL19623241W","title":"The City of Brass","text":"Nahri survives in Cairo through persuasion and abilities she does not entirely understand. An encounter with a djinn draws her into a much larger magical world and towards the city of Daevabad. There, competing histories and political factions make it difficult to decide whom to believe. The City of Brass opens the Daevabad trilogy, bringing an outsider's discovery of her powers into conflict with a society divided by inherited loyalties.","source":"https://openlibrary.org/works/OL19623241W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8392,"authorId":5079,"ol":"OL16653954W","title":"A Short Stay in Hell","text":"After his death, Soren Johansson discovers that the afterlife bears little resemblance to what he believed. He is sent to a vast library and given a task whose apparent simplicity becomes overwhelming: find the book containing his own life. A Short Stay in Hell follows the emotional and philosophical consequences of that search. Steven L. Peck uses a concise story to make immense stretches of time and uncertainty feel deeply unsettling.","source":"https://strangeviolineditions.com/news-2/","sourceType":"official_publisher","sourceName":"strangeviolineditions.com"},{"id":8406,"authorId":5086,"ol":"OL19670214W","title":"The wedding date","text":"Alexa and Drew meet when a power failure traps them in a lift. Drew needs a guest for a wedding, and their improvised arrangement becomes more enjoyable than either expected. Returning to separate lives leaves them negotiating distance, expectations and the possibility of something lasting. The Wedding Date begins Jasmine Guillory's connected romance novels with a relationship that must move beyond the convenience of pretending for a single event.","source":"https://openlibrary.org/works/OL19670214W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8410,"authorId":19,"ol":"OL5738149W","title":"Warbreaker","text":"Two princesses find their expected futures altered by an arranged marriage intended to prevent war. In the kingdom where one of them arrives, returned gods and powerful factions pursue interests that are not easy to read. Warbreaker links their experiences to a magic system involving colour and transferable Breath. Brandon Sanderson brings political manoeuvring and questions about trust into a fantasy novel that can be read without starting a long sequence.","source":"https://openlibrary.org/works/OL5738149W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8425,"authorId":5093,"ol":"OL21213411W","title":"The Bear and the Nightingale","text":"Vasya grows up in the Russian countryside, where stories about household spirits and the winter wilderness are part of daily life. She can perceive things that others increasingly dismiss or condemn. As pressure to abandon old customs grows, the protections around her home begin to weaken. The Bear and the Nightingale opens the Winternight trilogy, connecting folklore with a young woman's struggle to find room for her own choices.","source":"https://openlibrary.org/works/OL21213411W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8538,"authorId":586,"ol":"OL18147688W","title":"The Great Alone","text":"In 1974, Leni's father moves the family to Alaska in search of a different life. The beauty of their new surroundings comes with difficult preparations for winter and a dependence on neighbours. At home, his increasingly dangerous behaviour creates another threat that cannot be solved by practical skills alone. The Great Alone follows Leni's coming of age within a family whose isolation makes both love and escape complicated.","source":"https://openlibrary.org/works/OL18147688W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8643,"authorId":1529,"ol":"OL1846863W","title":"The Bean Trees","text":"Taylor leaves Kentucky hoping to build an independent life. On her journey west, she unexpectedly becomes responsible for a small girl and eventually settles in Tucson. Finding work and support brings her into a network of people dealing with their own uncertain circumstances. The Bean Trees explores care, friendship and the families people form beyond biological ties, while connecting Taylor's changing responsibilities to questions about migration and belonging.","source":"https://openlibrary.org/works/OL1846863W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8681,"authorId":19,"ol":"OL19960448W","title":"The Emperor's Soul","text":"Shai, a skilled magical forger facing execution, is offered a chance to survive by undertaking a secret commission. She must reconstruct the damaged soul of an emperor within a tightly limited time. Understanding the person she is meant to recreate requires more than technical ability. The Emperor's Soul makes a compact fantasy problem out of questions about art, authenticity and whether an individual's history can ever be fully understood by someone else.","source":"https://openlibrary.org/works/OL19960448W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":8959,"authorId":875,"ol":"OL17764484W","title":"My not so Perfect Life","text":"Katie presents a polished version of her London life even while her work and finances are far from ideal. Losing her advertising job sends her back to the family farm, where she helps develop a holiday business. The arrival of people from her former workplace unsettles her assumptions about them and herself. My Not So Perfect Life combines comedy and romance with the gap between appearances and everyday experience.","source":"https://openlibrary.org/works/OL17764484W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9001,"authorId":429,"ol":"OL16667087W","title":"Just Like Heaven","text":"Honoria Smythe-Smith is known for participating in her family's famously unsuccessful musical performances. Marcus, her brother's close friend, has long occupied a familiar place in her life. When circumstances bring them closer, the roles they assumed they understood become harder to sustain. Just Like Heaven begins Julia Quinn's Smythe-Smith Quartet, placing a friends-to-lovers romance within a Regency world of family expectations and social occasions.","source":"https://openlibrary.org/works/OL16667087W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9024,"authorId":5288,"ol":"OL20060313W","title":"The Alice network","text":"In 1947, Charlie St. Clair seeks a cousin who disappeared during the war. Her search brings her into contact with Eve Gardiner, whose experience in a women's espionage network during the First World War has left lasting wounds. The Alice Network alternates their stories as a new investigation draws out an older one. Kate Quinn connects historical suspense with the consequences of secrecy, betrayal and difficult choices made under occupation.","source":"https://openlibrary.org/works/OL20060313W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9093,"authorId":355,"ol":"OL20794199W","title":"His & Hers","text":"A murder in Blackdown draws reporter Anna Andrews back to a place she would prefer to avoid. Detective Jack Harper investigates while concealing connections that could make him a suspect himself. His & Hers tells the story through perspectives whose omissions matter as much as their revelations. Alice Feeney builds a psychological thriller around conflicting accounts, shared history and the problem of deciding which version of events deserves belief.","source":"https://openlibrary.org/works/OL20794199W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9156,"authorId":346,"ol":"OL20152797W","title":"The Hunting Party","text":"A group of old friends gathers at a remote Scottish lodge to celebrate New Year. Snow cuts them off while tensions beneath their familiar roles begin to emerge. When one of the group is killed, their shared history becomes part of the puzzle. The Hunting Party uses a confined cast and an isolated setting to examine friendships that have survived without necessarily remaining honest or kind.","source":"https://openlibrary.org/works/OL20152797W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9282,"authorId":5377,"ol":"OL19123425W","title":"We Are Legion","text":"Bob Johansson expects a comfortable future after selling his software company, but his life ends abruptly. When he becomes conscious again, his mind has been preserved in computer hardware and assigned to an interstellar exploration project. We Are Legion (We Are Bob) follows the opportunities and constraints of that new existence. Dennis E. Taylor combines technical problem-solving and humour with questions about autonomy, identity and what it means to continue as a person.","source":"https://openlibrary.org/works/OL19123425W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9313,"authorId":54,"ol":"OL15942682W","title":"The Last Letter from Your Lover","text":"Journalist Ellie discovers an old letter while searching her newspaper's archive. Its plea for a woman to leave her husband draws her into the story of an earlier relationship, while her own romantic life remains unresolved. The Last Letter from Your Lover moves between the two periods to explore communication, missed opportunities and the pressures surrounding personal decisions. Jojo Moyes connects the search for a past truth with the possibility of changing a present life.","source":"https://openlibrary.org/works/OL15942682W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9318,"authorId":1543,"ol":"OL19976661W","title":"Bird box","text":"Something in the outside world makes looking at it dangerous, forcing survivors to organise life around closed windows and blindfolds. Malorie must take two young children down a river without relying on sight. Bird Box moves between that journey and the experiences that led to it. Josh Malerman builds horror from uncertainty, restricted perception and the difficulty of deciding when other people can be trusted.","source":"https://openlibrary.org/works/OL19976661W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9402,"authorId":5415,"ol":"OL8454235W","title":"The Thirteenth Tale","text":"The celebrated writer Vida Winter has offered many different versions of her past. Near the end of her life, she asks biographer Margaret Lea to record a story she claims is finally true. Margaret's investigation leads into a family history shaped by secrecy and loss, while touching on her own unresolved experiences. The Thirteenth Tale uses a gothic atmosphere and a story within a story to explore the uncertain relationship between memory and invention.","source":"https://openlibrary.org/works/OL8454235W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9527,"authorId":5452,"ol":"OL20625154W","title":"Dark Matter","text":"In 1937, Jack joins an Arctic expedition as a wireless operator, hoping to change the course of his life. At the remote camp of Gruhuken, the approaching polar night makes isolation increasingly oppressive. As companions leave, his unease becomes harder to dismiss. Michelle Paver's Dark Matter is a ghost story in which environmental danger and fear of an unseen presence reinforce one another, turning the decision to remain into a frightening commitment.","source":"https://openlibrary.org/works/OL20625154W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9548,"authorId":5295,"ol":"OL1911650W","title":"This Matter of Marriage","text":"Hallie approaches finding a husband as a goal that can be planned, but the dates she arranges repeatedly disappoint her. Her neighbour Steve is occupied with the collapse of his own marriage and hopes of repairing it. Their friendship develops alongside these separate romantic expectations. This Matter of Marriage follows the difference between the partner someone imagines wanting and the connection that may be forming much closer to home.","source":"https://openlibrary.org/works/OL1911650W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9582,"authorId":5471,"ol":"OL27412480W","title":"When in Rome","text":"Pop star Amelia Rose leaves her demanding public life for an impulsive break in Rome, Kentucky. When her car fails, she encounters Noah, a local baker who has little patience for celebrity disruption. A temporary stay gives them time to see beyond their first impressions. When in Rome combines a small-town setting with a romance about privacy, exhaustion and the possibility of being known as a person rather than a public image.","source":"https://openlibrary.org/works/OL27412480W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9735,"authorId":590,"ol":"OL19865296W","title":"The Island of Sea Women","text":"Mi-ja and Young-sook grow up in the diving community of Jeju, where women undertake dangerous work at sea. Their friendship develops amid social differences that cannot be separated from the island's history. Across decades of occupation, conflict and change, personal decisions acquire lasting consequences. The Island of Sea Women brings the physical world of the haenyeo into a story about loyalty, inherited divisions and the difficulty of repairing a damaged relationship.","source":"https://openlibrary.org/works/OL19865296W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9821,"authorId":5548,"ol":"OL24630972W","title":"The Paper Palace","text":"At her family's summer place on Cape Cod, Elle faces a decision involving her marriage and a relationship reaching back into childhood. A single day is interwoven with memories that explain why the choice carries so much weight. The Paper Palace explores how love and family responsibilities are shaped by experiences people have not fully shared. Miranda Cowley Heller places a vivid natural setting around a story containing painful memories and unresolved harm.","source":"https://openlibrary.org/works/OL24630972W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9891,"authorId":5086,"ol":"OL19761168W","title":"The proposal","text":"Nikole rejects an unexpected marriage proposal delivered in front of a stadium crowd. Carlos helps her escape the immediate attention, and their acquaintance develops into a relationship both initially describe as casual. As their time together becomes more important, the limits they set are tested. The Proposal follows two people negotiating independence, public expectations and the risk of acknowledging feelings that no longer fit their original agreement.","source":"https://openlibrary.org/works/OL19761168W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":9908,"authorId":590,"ol":"OL14927217W","title":"Snow Flower and the Secret Fan","text":"In nineteenth-century China, Lily forms a formal lifelong bond with Snow Flower. Their communication through a women's writing system offers intimacy within lives constrained by family expectations and unequal social circumstances. As they grow older, changes in fortune and interpretation put the relationship under strain. Snow Flower and the Secret Fan explores friendship through memory, showing how affection can coexist with assumptions that remain unspoken until they cause lasting damage.","source":"https://openlibrary.org/works/OL14927217W","sourceType":"official_catalog","sourceName":"Open Library"},{"id":10032,"authorId":138,"ol":"OL20642211W","title":"To Be Taught, If Fortunate","text":"A small scientific crew travels to distant worlds using technology that allows their bodies to adapt to unfamiliar environments. Their purpose is to observe and understand life beyond Earth, while communication with home becomes increasingly uncertain. To Be Taught, If Fortunate follows the emotional as well as practical demands of that work. Becky Chambers uses a standalone novella to ask what exploration is for and what responsibilities discovery brings.","source":"https://openlibrary.org/works/OL20642211W","sourceType":"official_catalog","sourceName":"Open Library"}],"editions":[{"id":21,"authorId":17,"ol":"OL59800W","title":"The Left Hand of Darkness","isbn":"9780441478125","isbn10":"0441478123","olid":"OL7525849M","publisher":"Ace","format":"paperback","language":"eng","cover":"https://images.penguinrandomhouse.com/cover/9780441478125","coverSha256":"fbce7d66a268f80adae87156a03c9a02bcaa4c5796992dbdfc01f356242f2a41","source":"https://www.penguinrandomhouseretail.com/book/?isbn=9780441478125","bibliography":"https://openlibrary.org/books/OL7525849M"},{"id":26,"authorId":21,"ol":"OL71037W","title":"The Lion, the Witch and the Wardrobe","isbn":"9780064404990","isbn10":"0064404994","olid":"OL27900766M","publisher":"HarperTrophy","format":"paperback","language":"eng","cover":"https://covers.openlibrary.org/b/id/15244869-L.jpg","coverSha256":"1a8922189a5ec69d57144d9b9102042712ac0c3ceac6482843722086688508de","source":"https://www.thebookco.com/the-lion-the-witch-and-the-wardrobe-9780064404990","bibliography":"https://openlibrary.org/books/OL27900766M"},{"id":2723,"authorId":1,"ol":"OL17837968W","title":"Artemis","isbn":"9780553448122","isbn10":"0553448129","olid":"OL26424863M","publisher":"Crown","format":"hardcover","language":"eng","cover":"https://images1.penguinrandomhouse.com/cover/9780553448122","coverSha256":"6e33fcc1a9ec513dfa00e652476395738643f010b5eb2f0b8aa99f216370e9f6","source":"https://www.penguinrandomhouse.com/books/250305/artemis-by-andy-weir/9780553448122/","bibliography":"https://openlibrary.org/books/OL26424863M"}],"years":[{"id":8392,"year":2012,"source":"https://strangeviolineditions.com/news-2/","old":2009,"ol":"OL16653954W","authorId":5079},{"id":9688,"year":2019,"source":"https://www.simonandschuster.com/books/This-Tender-Land/William-Kent-Krueger/9781476749297","old":2016,"ol":"OL20120987W","authorId":5502}]}$records$; r jsonb; eid bigint; BEGIN
FOR r IN SELECT value FROM jsonb_array_elements(data->'descriptions') LOOP
 DELETE FROM public.catalog_work_descriptions WHERE work_id=(r->>'id')::bigint AND bound_author_id=(r->>'authorId')::bigint AND language='en' AND text=r->>'text' AND review_batch='en-reading-lists-complete-20261116'; IF NOT FOUND THEN RAISE EXCEPTION 'Description changed: %',r->>'id'; END IF;
END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(data->'editions') LOOP
 DELETE FROM public.catalog_edition_metadata WHERE work_id=(r->>'id')::bigint AND bound_author_id=(r->>'authorId')::bigint AND bound_title=r->>'title' AND bound_isbn13=r->>'isbn' AND cover_url=r->>'cover' AND review_batch='en-reading-lists-complete-20261116' RETURNING edition_id INTO eid; IF NOT FOUND THEN RAISE EXCEPTION 'Metadata changed: %',r->>'id'; END IF;
 DELETE FROM public.editions WHERE id=eid AND work_id=(r->>'id')::bigint AND isbn_13=r->>'isbn' AND open_library_edition_id=r->>'olid'; IF NOT FOUND THEN RAISE EXCEPTION 'Edition changed'; END IF;
END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(data->'years') LOOP
 UPDATE public.works SET first_publish_year=(r->>'old')::int WHERE id=(r->>'id')::bigint AND author_id=(r->>'authorId')::bigint AND open_library_id=r->>'ol' AND first_publish_year=(r->>'year')::int; IF NOT FOUND THEN RAISE EXCEPTION 'Year changed'; END IF;
END LOOP; END $operation$; COMMIT;
